5	{"parentUuid":"55307838-2959-4597-a802-56d455b66d57","isSidechain":false,"attachment":{"type":"hook_success","hookName":"SessionStart:startup","toolUseID":"953b6139-9e48-4903-8a18-9444106d906e","hookEvent":"SessionStart","content":"","stdout":"{
